function main(input) {
  const text: string = String(input.content ?? '');
  const lines = text.split(/\r?\n/).filter(l => l.trim() !== '');
  if (lines.length < 2) throw new Error('アンケートにデータ行がありません');
  const unq = (s: string) => s.trim().replace(/^"|"$/g, '');
  const header = lines[0].split(',').map(unq);
  let idx = header.findIndex(h => h.includes('推奨'));
  if (idx < 0) idx = header.findIndex(h => /recommend|nps/i.test(h));
  if (idx < 0) throw new Error('推奨度の列が見つかりません');
  const scores: number[] = [];
  for (const line of lines.slice(1)) {
    const v = Number(unq(line.split(',')[idx] ?? ''));
    if (Number.isInteger(v) && v >= 0 && v <= 10) scores.push(v);
  }
  const responses = scores.length;
  const promoters = scores.filter(s => s >= 9).length;
  const detractors = scores.filter(s => s <= 6).length;
  const nps = responses === 0 ? 0 : Math.round((promoters / responses - detractors / responses) * 100);
  return { responses, promoters, detractors, nps };
}

