const text: string = String(input.content ?? "");
const lines = text.split(/\r?\n/).filter((l) => l.trim() !== "");
if (lines.length < 2) throw new Error("回答データがありません");
const header = lines[0].split(",").map((h) => h.trim().replace(/^"|"$/g, ""));
const idx = header.findIndex((h) => /推奨|recommend/i.test(h));
if (idx < 0) throw new Error("推奨度の列が見つかりません");
let responses = 0;
let promoters = 0;
let detractors = 0;
for (const line of lines.slice(1)) {
  const cell = (line.split(",")[idx] ?? "").trim().replace(/^"|"$/g, "");
  if (cell === "") continue;
  const v = Number(cell);
  if (!Number.isInteger(v) || v < 0 || v > 10) continue;
  responses++;
  if (v >= 9) promoters++;
  else if (v <= 6) detractors++;
}
if (responses === 0) throw new Error("有効な回答がありません");
const nps = Math.round((promoters / responses - detractors / responses) * 100);
return { responses, promoters, detractors, nps };

