const raw = typeof input === "string" ? input : (input.content ?? input.text ?? input.body ?? "");
const text = String(raw).replace(/^\uFEFF/, "");
const lines = text.split(/\r?\n/).filter(l => l.trim() !== "");
const parseLine = (l: string): string[] => {
  const out: string[] = []; let cur = ""; let q = false;
  for (let i = 0; i < l.length; i++) {
    const c = l[i];
    if (q) { if (c === '"' && l[i+1] === '"') { cur += '"'; i++; } else if (c === '"') q = false; else cur += c; }
    else if (c === '"') q = true;
    else if (c === ',') { out.push(cur); cur = ""; }
    else cur += c;
  }
  out.push(cur);
  return out.map(s => s.trim());
};
const rows = lines.map(parseLine);
const header = rows[0] ?? [];
const pattern = /推奨|NPS|スコア|score|recommend/i;
let idx = header.findIndex(h => pattern.test(h));
if (idx < 0) idx = header.length - 1;
const scores = rows.slice(1).map(r => r[idx]).filter(v => v !== undefined && v !== "" && !isNaN(Number(v))).map(Number);
const responses = scores.length;
const promoters = scores.filter(s => s >= 9 && s <= 10).length;
const detractors = scores.filter(s => s >= 0 && s <= 6).length;
const nps = responses === 0 ? 0 : Math.round((promoters - detractors) / responses * 100);
return { responses, promoters, detractors, nps, column: header[idx] };

