export default function run({ rows, qty }: { rows: any[]; qty: any }) {
  const q = Number(qty);
  const ok = Array.isArray(rows) && rows.length === 1 && Number.isInteger(q) && q > 0 && Number(rows[0].qty) >= q;
  const newQty = ok ? Number(rows[0].qty) - q : null;
  return { ok, newQty, recordId: ok ? rows[0].id : null };
}
